// naive per-IP fixed-window rate limiter
const hits = new Map();
function allow(ip) {
  const t = Date.now(), w = 60000;
  const e = hits.get(ip) || { n: 0, start: t };
  if (t - e.start > w) { e.n = 0; e.start = t; }
  e.n++; hits.set(ip, e);
  return e.n <= 100;   // 100 req/min
}
