// token bucket (single process)
let tokens = 100, last = Date.now();
const RATE = 100, CAP = 100;  // refill tokens/sec
function allow() {
  const now = Date.now();
  tokens = Math.min(CAP, tokens + (now - last) / 1000 * RATE);
  last = now;
  if (tokens >= 1) { tokens--; return true; }
  return false;
}
