// retry with backoff + circuit breaker concept
async function callWithRetry(fn, { retries = 3, backoff = 100 } = {}) {
  for (let i = 0; i < retries; i++) {
    if (!circuit.closed) throw new Error('open');
    try { return await fn(); }
    catch (e) {
      if (i === retries - 1) throw e;
      await sleep(backoff * Math.pow(2, i) + Math.random() * 50);
    }
  }
}
// circuit breaker: failures -> open -> half-open -> closed

